//
// CARD_VERSION is the single source of truth for the released version and must
// match package.json and package-lock.json. test/unit/build-artifact.test.js
// and test/unit/characterization-registration.test.js both assert that,
// against the built bundle's window.roomClimateCardVersion, so the three can
// never silently drift apart.
//
// Deliberately no changelog here (documented convention since 2.9.0): version
// history and rationale live in the internal technical documentation, not in
// the shipped file.

const CARD_TYPE = "room-climate-card";
const CARD_NAME = "Room Climate Card";
const CARD_VERSION = "2.36.1";

// Language codes and their Intl locales.
//
// Separate from registry.js on purpose: the language files themselves need the
// plural helpers in formatters.js, and formatters.js needs these locale
// mappings. Keeping the mappings here breaks what would otherwise be a cycle
// (languages -> formatters -> registry -> languages).

// Card default, and the fallback for any key a translation is missing.
const DEFAULT_LANGUAGE = "en";

// Base language code -> an Intl-compatible locale, used for number, time and
// plural-rule formatting. A new language needs an entry here as well as its
// own file under languages/.
const NUMBER_LOCALE_BY_LANGUAGE = {
  de: "de-DE",
  en: "en-US",
  nl: "nl-NL",
  fr: "fr-FR",
  it: "it-IT",
  es: "es",
  ru: "ru",
  pl: "pl",
  ko: "ko",
  ja: "ja",
  zh: "zh",
  nb: "nb-NO",
  sv: "sv-SE",
  lv: "lv-LV",
};

// Locale-aware formatting, plus the plural helpers the language files use.
//
// Number.prototype.toLocaleString()/Date.prototype.toLocaleTimeString() each
// construct a fresh Intl formatter internally on every call; a card with
// several rooms formats a dozen-plus numbers per render, so everything here
// reuses one cached formatter per locale/digits combination (built once,
// formats many times).


const NUMBER_FORMAT_CACHE = new Map();
const TIME_FORMAT_CACHE = new Map();
const PLURAL_RULES_CACHE = new Map();

function getNumberFormat(locale, digits) {
  const key = `${locale}|${digits}`;
  let fmt = NUMBER_FORMAT_CACHE.get(key);
  if (!fmt) {
    fmt = new Intl.NumberFormat(locale, { minimumFractionDigits: digits, maximumFractionDigits: digits });
    NUMBER_FORMAT_CACHE.set(key, fmt);
  }
  return fmt;
}

function getTimeFormat(locale) {
  let fmt = TIME_FORMAT_CACHE.get(locale);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat(locale, { hour: "2-digit", minute: "2-digit", hour12: false });
    TIME_FORMAT_CACHE.set(locale, fmt);
  }
  return fmt;
}

// Languages with more than two plural categories (Russian, Polish, Latvian)
// use these instead of hand-written one-vs-other rules.
function getPluralCategory(language, count) {
  let rules = PLURAL_RULES_CACHE.get(language);
  if (!rules) {
    rules = new Intl.PluralRules(NUMBER_LOCALE_BY_LANGUAGE[language] || language);
    PLURAL_RULES_CACHE.set(language, rules);
  }
  return rules.select(Number(count));
}

function selectPlural(language, count, forms) {
  return forms[getPluralCategory(language, count)] ?? forms.other;
}

// Formats a number in the given language. The digit count is decided by the
// caller (config override, then the metric's own default), because that is a
// presentation decision this module has no way to resolve.
function formatNumber(language, value, digits) {
  return getNumberFormat(NUMBER_LOCALE_BY_LANGUAGE[language], digits).format(Number(value));
}

// Formats an ISO timestamp as local "HH:MM" (hour12:false keeps this
// consistent across languages); null for a missing/invalid timestamp.
function formatTimeOfDay(language, isoString) {
  if (typeof isoString !== "string" || !isoString.trim()) return null;
  const date = new Date(isoString);
  if (Number.isNaN(date.getTime())) return null;
  return getTimeFormat(NUMBER_LOCALE_BY_LANGUAGE[language]).format(date);
}

// Module-load self-check for translation key parity.
//
// Runs once, when the card is loaded, and warns if a language's key set
// differs from the reference language. A missing or extra key in a new or
// edited translation is therefore caught immediately — by whoever loads the
// card, including a community contributor testing their own translation —
// instead of silently falling back to English at runtime, where nobody would
// notice which key was actually missing.
//
// Cheap: a set difference over ~80 keys per language, once per page load.

function verifyTranslationKeyParity(translations, referenceLanguage) {
  const referenceKeys = new Set(Object.keys(translations[referenceLanguage]));
  for (const lang of Object.keys(translations)) {
    if (lang === referenceLanguage) continue;
    const keys = new Set(Object.keys(translations[lang]));
    const missing = [...referenceKeys].filter((k) => !keys.has(k));
    const extra = [...keys].filter((k) => !referenceKeys.has(k));
    if (missing.length || extra.length) {
      console.warn(
        `Room Climate Card: TRANSLATIONS["${lang}"] is out of sync with "${referenceLanguage}"` +
          (missing.length ? ` — missing: ${missing.join(", ")}` : "") +
          (extra.length ? ` — extra: ${extra.join(", ")}` : "")
      );
    }
  }
}

